import{_ as h,o as t,c as a,a2 as i}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"Hướng dẫn Quan sát Trước, Sau đó Can thiệp Hạn chế","description":"","frontmatter":{},"headers":[],"relativePath":"vi/0083-先观测后有限干涉准则.md","filePath":"vi/0083-先观测后有限干涉准则.md"}'),c={name:"vi/0083-先观测后有限干涉准则.md"};function u(g,n,o,l,r,p){return t(),a("div",null,[...n[0]||(n[0]=[i('<h1 id="huong-dan-quan-sat-truoc-sau-đo-can-thiep-han-che" tabindex="-1">Hướng dẫn Quan sát Trước, Sau đó Can thiệp Hạn chế <a class="header-anchor" href="#huong-dan-quan-sat-truoc-sau-đo-can-thiep-han-che" aria-label="Permalink to &quot;Hướng dẫn Quan sát Trước, Sau đó Can thiệp Hạn chế&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>83</td></tr><tr><td>Mô-đun</td><td>Tương tác Liên mặt phẳng và Quy tắc Thời gian</td></tr><tr><td>Từ khóa cốt lõi</td><td>Quan sát trước, can thiệp hạn chế, giao thức quan sát, ngưỡng can thiệp, đánh giá nhân quả</td></tr></tbody></table><h2 id="_1-triet-ly-cot-loi-cua-huong-dan" tabindex="-1">1. Triết lý Cốt lõi của Hướng dẫn <a class="header-anchor" href="#_1-triet-ly-cot-loi-cua-huong-dan" aria-label="Permalink to &quot;1. Triết lý Cốt lõi của Hướng dẫn&quot;">​</a></h2><p>&quot;Quan sát trước, sau đó can thiệp hạn chế&quot; là hướng dẫn chính cho hoạt động lùi lại thời gian và khảo cổ liên mặt phẳng của Hengyuanzhou, triết lý cốt lõi của nó có thể được tóm tắt trong mười sáu ký tự: &quot;Quan sát mà không chạm vào, đo lường mà không làm phiền, phân tích trước khi hành động, hành động có giới hạn.&quot; Việc thiết lập hướng dẫn này dựa trên sự tôn kính sâu sắc đối với luật nhân quả của vũ trụ — bất kỳ can thiệp trực tiếp nào vào quá khứ hoặc mặt phẳng khác đều có thể gây ra phản ứng chuỗi nhân quả không thể dự đoán, và quan sát trước đầy đủ là phương tiện đáng tin cậy duy nhất để giảm thiểu rủi ro.</p><p>Cơ sở triết học của hướng dẫn là nguyên tắc &quot;khiêm nhường nhận thức&quot;. Hengyuanzhou thừa nhận rằng ngay cả những người mạnh mẽ tối cao ở một mặt phẳng cũng không thể nắm vững hoàn toàn tất cả các mối quan hệ nhân quả của một nút thời gian hoặc một nền văn minh mặt phẳng. Do đó, trước khi thực hiện bất kỳ hành động can thiệp nào, phải thực hiện quan sát toàn diện với thái độ thận trọng nhất, hiểu cấu trúc nhân quả và xu hướng tiến hóa của đối tượng mục tiêu một cách đầy đủ nhất có thể. Chỉ dưới tiền đề dữ liệu quan sát đầy đủ và đánh giá rủi ro rõ ràng, can thiệp hạn chế mới được phép.</p><p>&quot;Quan sát trước, sau đó can thiệp hạn chế&quot; không phải là hai bước độc lập, mà là một vòng lặp hoạt động hữu cơ: quan sát cung cấp cơ sở cho can thiệp, và kết quả can thiệp lại phản hồi làm dữ liệu quan sát mới, cả hai tuần hoàn và tiến triển dần dần. Vòng lặp này đảm bảo rằng mỗi lần can thiệp đều được xây dựng trên cơ sở nhận thức mới nhất và đầy đủ nhất.</p><h2 id="_2-quy-pham-hoat-đong-cua-giai-đoan-quan-sat" tabindex="-1">2. Quy phạm Hoạt động của Giai đoạn Quan sát <a class="header-anchor" href="#_2-quy-pham-hoat-đong-cua-giai-đoan-quan-sat" aria-label="Permalink to &quot;2. Quy phạm Hoạt động của Giai đoạn Quan sát&quot;">​</a></h2><p>Giai đoạn quan sát là nền tảng của toàn bộ quy trình hoạt động, chất lượng của nó trực tiếp quyết định sự an toàn và hiệu quả của can thiệp sau này. Giai đoạn quan sát phải tuân theo các quy phạm hoạt động sau:</p><h3 id="_2-1-yeu-cau-ve-thoi-luong-quan-sat" tabindex="-1">2.1 Yêu cầu về Thời lượng Quan sát <a class="header-anchor" href="#_2-1-yeu-cau-ve-thoi-luong-quan-sat" aria-label="Permalink to &quot;2.1 Yêu cầu về Thời lượng Quan sát&quot;">​</a></h3><p>Thời lượng quan sát không được dưới 1% tổng thời lượng của giai đoạn mục tiêu, và thời lượng tuyệt đối không được dưới 72 giờ thời gian tiêu chuẩn của mặt phẳng自己. Ví dụ, để thực hiện quan sát lùi lại trên một giai đoạn lịch sử có thời lượng 100 năm, giai đoạn quan sát thuần túy không được dưới 1 năm; để quan sát một giai đoạn có thời lượng 10 năm, giai đoạn quan sát thuần túy không được dưới 72 giờ. Yêu cầu về thời lượng tối thiểu này đảm bảo rằng người quan sát có thể nắm bắt được những thay đổi định kỳ và xu hướng dài hạn trong giai đoạn mục tiêu, tránh những phán đoán một phía do cửa sổ quan sát quá ngắn.</p><h3 id="_2-2-yeu-cau-ve-chieu-quan-sat" tabindex="-1">2.2 Yêu cầu về Chiều Quan sát <a class="header-anchor" href="#_2-2-yeu-cau-ve-chieu-quan-sat" aria-label="Permalink to &quot;2.2 Yêu cầu về Chiều Quan sát&quot;">​</a></h3><p>Quan sát phải bao gồm năm chiều sau, không được thiếu bất kỳ chiều nào:</p><table tabindex="0"><thead><tr><th>Chiều Quan sát</th><th>Nội dung Cụ thể</th><th>Phương pháp Quan sát</th></tr></thead><tbody><tr><td>Chiều vật chất</td><td>Môi trường địa lý, hệ sinh thái, cơ sở hạ tầng, phân bố nguồn lực vật chất</td><td>Quét không gian, phân tích vật chất</td></tr><tr><td>Chiều năng lượng</td><td>Phân bố mật độ năng lượng, tham số luật pháp, mô hình dòng chảy năng lượng</td><td>Phân tích phổ năng lượng, phát hiện luật pháp</td></tr><tr><td>Chiều sự sống</td><td>Phân bố loài, số lượng quần thể, tình trạng sức khỏe, mức độ tiến hóa</td><td>Quét dấu hiệu sự sống, lấy mẫu gen</td></tr><tr><td>Chiều ý thức</td><td>Hình thức văn minh, cấu trúc xã hội, quan niệm tư tưởng, xu hướng ý thức tập thể</td><td>Giám sát thụ động miền ý thức, phân tích văn hóa</td></tr><tr><td>Chiều nhân quả</td><td>Chuỗi nhân quả quan trọng, nút lịch sử, xu hướng tiến hóa, rủi ro tiềm ẩn</td><td>Theo dõi chuỗi nhân quả, suy luận xu hướng</td></tr></tbody></table><h3 id="_2-3-yeu-cau-ve-trung-lap-quan-sat" tabindex="-1">2.3 Yêu cầu về Trung lập Quan sát <a class="header-anchor" href="#_2-3-yeu-cau-ve-trung-lap-quan-sat" aria-label="Permalink to &quot;2.3 Yêu cầu về Trung lập Quan sát&quot;">​</a></h3><p>Giai đoạn quan sát phải duy trì sự trung lập nghiêm ngặt, người quan sát không được ảnh hưởng đến đối tượng quan sát bằng bất kỳ cách nào. Các hành động bị cấm cụ thể bao gồm: thực hiện bất kỳ hình thức giao tiếp nào với đối tượng quan sát, để lại bất kỳ dấu vết vật chất hoặc năng lượng nào trong khu vực quan sát, hướng dẫn hoặc gợi ý hành vi của đối tượng quan sát, và giải phóng bất kỳ biến động ý chí nào có thể được cảm nhận trong miền ý thức.</p><p>Trạng thái tồn tại của người quan sát trong giai đoạn quan sát phải là &quot;nhận thức thụ động thuần túy&quot;, tức là chỉ nhận thông tin mà không xuất ra bất kỳ thông tin nào. Thiết bị neo neo sẽ tạo ra một lớp &quot;trường chắn quan sát&quot; cho người quan sát, đảm bảo rằng sự tồn tại của người quan sát không bị đối tượng quan sát cảm nhận, đồng thời ngăn chặn người quan sát vô tình giải phóng tín hiệu gây nhiễu.</p><h2 id="_3-đinh-nghia-va-nguong-cua-can-thiep-han-che" tabindex="-1">3. Định nghĩa và Ngưỡng của Can thiệp Hạn chế <a class="header-anchor" href="#_3-đinh-nghia-va-nguong-cua-can-thiep-han-che" aria-label="Permalink to &quot;3. Định nghĩa và Ngưỡng của Can thiệp Hạn chế&quot;">​</a></h2><p>Sau khi hoàn thành giai đoạn quan sát, đội ngũ hoạt động phải trình &quot;Báo cáo Quan sát và Đánh giá Khả thi Can thiệp&quot;, và chỉ sau khi được Ủy ban Luật pháp Thời gian hoặc Cục Quản lý Mặt phẳng phê duyệt, mới có thể bước vào giai đoạn can thiệp hạn chế. &quot;Hạn chế&quot; trong &quot;can thiệp hạn chế&quot; được thể hiện ở ba cấp độ sau:</p><h3 id="_3-1-pham-vi-han-che" tabindex="-1">3.1 Phạm vi Hạn chế <a class="header-anchor" href="#_3-1-pham-vi-han-che" aria-label="Permalink to &quot;3.1 Phạm vi Hạn chế&quot;">​</a></h3><p>Hành động can thiệp phải được giới hạn nghiêm ngặt trong &quot;khu vực cho phép can thiệp&quot; được quy định trong tài liệu phê duyệt, khu vực này thường không vượt quá 1% tổng diện tích khu vực quan sát. Bất kỳ hành động can thiệp nào ngoài khu vực được phép đều được coi là hoạt động vi phạm, người vận hành sẽ phải chịu trách nhiệm pháp lý.</p><h3 id="_3-2-muc-đo-han-che" tabindex="-1">3.2 Mức độ Hạn chế <a class="header-anchor" href="#_3-2-muc-đo-han-che" aria-label="Permalink to &quot;3.2 Mức độ Hạn chế&quot;">​</a></h3><p>Đầu ra năng lượng và lượng tiêm thông tin của can thiệp không được vượt quá &quot;ngưỡng can thiệp&quot;. Ngưỡng can thiệp được xác định động theo độ nhạy nhân quả của đối tượng mục tiêu, công thức tính là: ngưỡng can thiệp = tổng năng lượng khu vực mục tiêu × hệ số độ nhạy nhân quả × 0,0001. Hệ số độ nhạy nhân quả có giá trị từ 0,1 đến 10; mức độ văn minh càng cao, nút lịch sử càng quan trọng, hệ số càng lớn. Điều này có nghĩa là ngưỡng can thiệp tại các nút lịch sử quan trọng là cực kỳ thấp, gần như không cho phép bất kỳ tiêm năng lượng thực chất nào.</p><h3 id="_3-3-thoi-gian-han-che" tabindex="-1">3.3 Thời gian Hạn chế <a class="header-anchor" href="#_3-3-thoi-gian-han-che" aria-label="Permalink to &quot;3.3 Thời gian Hạn chế&quot;">​</a></h3><p>Thời gian kéo dài của hành động can thiệp không được vượt quá 10% tổng thời lượng của giai đoạn quan sát, và thời lượng tuyệt đối không được vượt quá 24 giờ thời gian tiêu chuẩn của mặt phẳng自己. Sau khi can thiệp kết thúc, người vận hành phải ngay lập tức rút khỏi giai đoạn mục tiêu hoặc mặt phẳng mục tiêu, không được ở lại.</p><h2 id="_4-đanh-gia-va-sua-chua-nhan-qua-sau-can-thiep" tabindex="-1">4. Đánh giá và Sửa chữa Nhân quả Sau Can thiệp <a class="header-anchor" href="#_4-đanh-gia-va-sua-chua-nhan-qua-sau-can-thiep" aria-label="Permalink to &quot;4. Đánh giá và Sửa chữa Nhân quả Sau Can thiệp&quot;">​</a></h2><p>Sau khi can thiệp hạn chế kết thúc, đội ngũ hoạt động phải ngay lập tức thực hiện &quot;đánh giá nhân quả sau can thiệp&quot;, giám sát những thay đổi trong chuỗi nhân quả do hành động can thiệp gây ra thông qua mạng lưới neo. Nội dung đánh giá bao gồm: mức độ lệch nhân quả, phạm vi lan truyền của độ lệch, xu hướng tiến hóa dài hạn của độ lệch, và liệu có rủi ro nghịch lý hay không.</p><p>Nếu đánh giá phát hiện rằng độ lệch nhân quả vượt quá phạm vi có thể chấp nhận được (mức độ lệch vượt quá 0,01% tổng lượng nhân quả của khu vực mục tiêu), đội ngũ hoạt động phải ngay lập tức khởi động &quot;quy trình sửa chữa nhân quả&quot;. Các phương pháp sửa chữa nhân quả bao gồm: tiêm thông tin bù đắp vào các nút thời gian tiếp theo, điều chỉnh tinh tế chuỗi nhân quả thông qua mạng lưới neo, và trong trường hợp cực kỳ nghiêm trọng, thực hiện lùi lại lần thứ hai để trung hòa tác động của can thiệp trước đó.</p><p>Tất cả các hành động can thiệp và kết quả đánh giá nhân quả của chúng phải được ghi vào &quot;Kho lưu trữ Hoạt động Thời gian&quot;, được lưu trữ vĩnh viễn để sử dụng cho kiểm toán và nghiên cứu sau này.</p><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>Hướng dẫn quan sát trước, sau đó can thiệp hạn chế là tinh hoa trí tuệ của Hengyuanzhou trong lĩnh vực hoạt động thời gian và mặt phẳng. Với quan sát đầy đủ làm tiền đề, ngưỡng nghiêm ngặt làm biên giới, và đánh giá sau làm đảm bảo, nó xây dựng một mô hình hoạt động &quot;hiểu trước khi hành động, hành động có giới hạn&quot;. Mục đích cơ bản của hướng dẫn này không phải là trói tay chân của việc khám phá, mà là đảm bảo rằng mỗi lần khám phá không diễn ra với cái giá phải trả là phá hủy trật tự nhân quả của vũ trụ.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>82-Nguyên tắc Cơ bản của Lùi lại Thời gian</li><li>84-Tổng cương Nghị định thư Khảo cổ</li><li>89-Cơ chế Phòng ngừa và Kiểm soát Nghịch lý Thời gian</li></ul>',32)])])}const q=h(c,[["render",u]]);export{s as __pageData,q as default};
